"""Türkçe metin işleme fonksiyonları."""


# Türkçe I <-> ı, İ <-> i dönüşüm kuralları
# tr_lower: I -> ı, İ -> i
# tr_upper: i -> İ, ı -> I
# Diğer harfler normal Python .lower()/.upper() ile aynıdır

_TR_LOWER_SPECIAL = {
    'I': 'ı',
    'İ': 'i',
}

_TR_UPPER_SPECIAL = {
    'i': 'İ',
    'ı': 'I',
}


def tr_lower(s: str) -> str:
    """String'i Türkçe kurallarla küçük harfe çevirir.

    - I -> ı (normal Python lower I->i yapar, biz ı istiyoruz)
    - İ -> i
    - Diğer harfler normal .lower() ile aynıdır
    """
    if not s:
        return s
    result = []
    for ch in s:
        if ch in _TR_LOWER_SPECIAL:
            result.append(_TR_LOWER_SPECIAL[ch])
        else:
            result.append(ch.lower())
    return ''.join(result)


def tr_upper(s: str) -> str:
    """String'i Türkçe kurallarla büyük harfe çevirir.

    - i -> İ (normal Python upper i->I yapar, biz İ istiyoruz)
    - ı -> I
    - Diğer harfler normal .upper() ile aynıdır
    """
    if not s:
        return s
    result = []
    for ch in s:
        if ch in _TR_UPPER_SPECIAL:
            result.append(_TR_UPPER_SPECIAL[ch])
        else:
            result.append(ch.upper())
    return ''.join(result)


# Türkçe küçük harf sırası: 0-9, sonra a b c ç d e f g ğ h ı i j k l m n o ö p q r s ş t u ü v w x y z
_TR_ALFABE = '0123456789abcçdefgğhıijklmnoöpqrsştuüvwxyz'
_TR_ORD = {ch: i for i, ch in enumerate(_TR_ALFABE)}


def _tr_lower_ch(ch: str) -> str:
    """Tek bir karakteri Türkçe kurallarla küçük harfe çevirir."""
    return _TR_LOWER_SPECIAL.get(ch, ch.lower())


def _sort_key(word: str):
    """Bir kelimenin Türkçe alfabe sıralama anahtarını üretir.

    Alfabelde olmayan karakterler en başta (kendiler arası ord() sırasına göre).
    Alfabelde olanlar sırasıyla.
    Önek ise kısa önce gelir.
    """
    key_parts = []
    for ch in word:
        lower_ch = _tr_lower_ch(ch)
        if lower_ch in _TR_ORD:
            key_parts.append((0, _TR_ORD[lower_ch]))
        else:
            # Alfabelde olmayan: (-1, ord(ch)) -> hepsi en başta, kendi aralarında ord sırası
            key_parts.append((-1, ord(ch)))
    return key_parts


def tr_sorted(words: list[str]) -> list[str]:
    """Kelime listesini Türkçe alfabe sırasına göre sıralar.

    - Case-insensitive (Türkçe kurallarla küçük harfe çevirip karşılaştırır).
    - Girdi listesi değiştirilmez.
    - Eşit sayılan kelimeler girdideki sıralarını korur (kararlı sıralama).
    - Önek ise kısa kelime önce gelir.
    """
    indexed = list(enumerate(words))

    def _key(item):
        idx, word = item
        return (_sort_key(word), idx)

    indexed_sorted = sorted(indexed, key=_key)

    return [word for _, word in indexed_sorted]

